pm.test('Respuesta contiene datos del pago', function () {
    const jsonData = pm.response.json();
    const hasData = jsonData.hasOwnProperty('data') || jsonData.hasOwnProperty('pago') || jsonData.hasOwnProperty('cuota');
    pm.expect(hasData, "Expected 'data', 'pago' or 'cuota' in response").to.be.true;
});

pm.test('La cuota tiene estado pagada', function () {
    const jsonData = pm.response.json();
    const cuota = jsonData.data || jsonData.pago || jsonData.cuota || jsonData;
    const estado = cuota.estado || cuota.status;
    pm.expect(estado).to.be.oneOf(['pagada', 'pagado', 'paid']);
});

pm.test('La cuota tiene fecha de pago registrada', function () {
    const jsonData = pm.response.json();
    const cuota = jsonData.data || jsonData.pago || jsonData.cuota || jsonData;
    const fechaPago = cuota.fecha_pago || cuota.fechaPago || cuota.payment_date;
    pm.expect(fechaPago).to.not.be.null;
    pm.expect(fechaPago).to.not.be.undefined;
});

